window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"QumNUrflzgE","speaker":"Jeyhun Aziz oglu Bayramov","role":"Foreign Minister","country":"Azerbaijan","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=QumNUrflzgE","date":"20260926","title":"🇦🇿 Azerbaijan - Foreign Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1013,"words":2139,"counts":{"claims":31,"promises":0,"attacks":0},"topics":[{"topic":"UN reform","share":0.1854,"seconds":188},{"topic":"Middle Corridor","share":0.1308,"seconds":133},{"topic":"Intercultural dialogue","share":0.0896,"seconds":91},{"topic":"Azerbaijan urbanization","share":0.0749,"seconds":76},{"topic":"Azerbaijan aid","share":0.0734,"seconds":74},{"topic":"Azerbaijan economy","share":0.0671,"seconds":68},{"topic":"UNGA","share":0.0655,"seconds":66},{"topic":"Azerbaijan-Armenia conflict","share":0.0651,"seconds":66},{"topic":"Azerbaijan reconstruction","share":0.064,"seconds":65},{"topic":"Azerbaijan energy","share":0.0625,"seconds":63},{"topic":"Azerbaijan climate policy","share":0.0619,"seconds":63},{"topic":"Azerbaijan landmines","share":0.0598,"seconds":61}],"timeline":[[1,68,"UNGA"],[68,133,"UN reform"],[135,197,"UN reform"],[198,264,"Azerbaijan-Armenia conflict"],[266,331,"Azerbaijan reconstruction"],[332,393,"Azerbaijan landmines"],[394,485,"Intercultural dialogue"],[485,548,"Azerbaijan climate policy"],[550,624,"Azerbaijan aid"],[625,693,"Azerbaijan economy"],[695,771,"Azerbaijan urbanization"],[772,836,"Azerbaijan energy"],[837,898,"Middle Corridor"],[899,971,"Middle Corridor"],[973,1033,"UN reform"]],"stances":{"UNGA":"Jeyhun Aziz oglu Bayramov congratulates the new UNGA president and thanks the UN Secretary-General while noting that global challenges require collective action.","UN reform":"Jeyhun Aziz oglu Bayramov advocates for a reinvigorated and reformed multilateral system based on strict adherence to consistent international norms.","Azerbaijan-Armenia conflict":"Jeyhun Aziz oglu Bayramov states that normalization efforts have resulted in a historic peace declaration, the end of conflict, and increased regional stability through bilateral cooperation.","Azerbaijan reconstruction":"Jeyhun Aziz oglu Bayramov states that Azerbaijan is actively rebuilding liberated territories with green technology and smart cities, enabling over 90,000 people to return, while identifying landmine contamination as a remaining obstacle.","Azerbaijan landmines":"Jeyhun Aziz oglu Bayramov states that mine action is an essential prerequisite for fulfilling human rights and has been designated as a national sustainable development goal.","Intercultural dialogue":"Jeyhun Aziz oglu Bayramov states that Azerbaijan's multicultural society and international initiatives, such as the World Forum on Intercultural Dialogue, serve as a model for advancing cultural diversity and global solidarity.","Azerbaijan climate policy":"Azerbaijan successfully guided COP 29 negotiations to achieve historic agreements and is now focusing on implementing those outcomes through the UNFCCC climate week.","Azerbaijan aid":"Jeyhun Aziz oglu Bayramov states that Azerbaijan has expanded its international aid to over 140 countries since 2020 and reaffirms its commitment to the Sustainable Development Goals.","Azerbaijan economy":"Jeyhun Aziz oglu Bayramov states that Azerbaijan has achieved significant economic growth and poverty reduction while maintaining low public debt, and highlights the country's initiative in advancing sustainable development through transparent public service delivery.","Azerbaijan urbanization":"Jeyhun Aziz oglu Bayramov states that sustainable urbanization is a key pillar of Azerbaijan's approach and highlights the country's successful hosting of the World Urban Forum as a contribution to the global agenda.","Azerbaijan energy":"Jeyhun Aziz oglu Bayramov states that Azerbaijan is a reliable natural gas supplier and is actively investing in renewable energy to contribute to global energy security and the clean energy transition.","Middle Corridor":"Jeyhun Aziz oglu Bayramov states that Azerbaijan is evolving as a reliable energy partner and key transport hub, citing significant growth in cargo volumes along the Middle Corridor since 2022."},"claims":[{"t":70,"quote":"growing limitations of multilateral mechanisms continue to undermine our collective ability to respond effectively to current and emerging threats","topic":"UN reform","kind":"fact"},{"t":85,"quote":"true transformation is impossible without first restoring trust in the international order and demonstrating that multilateralism can once again deliver tangible results for all","topic":"UN reform","kind":"fact"},{"t":135,"quote":"All states large or small participularly developing countries must have the opportunity to participate equally in global decision making.","topic":"UN reform","kind":"fact"},{"t":145,"quote":"In this context, reform of the UN security is essential to make it more representative, effective, and responsive.","topic":"UN reform","kind":"fact"},{"t":173,"quote":"Even though the decadesl long conflict with Armenia brought immense tragedy to our people and left deep scars across our land, Azerbaijan has chosen to look ahead and turn the page of enmity.","topic":"UN reform","kind":"fact"},{"t":198,"quote":"Our normalization efforts produced historic results at the Washington peace summit last August where the leaders of Aarban and Armenia signed a joint declaration witnessed by President Trump of the United States of America.","topic":"Azerbaijan-Armenia conflict","kind":"fact"},{"t":212,"quote":"Through this declaration, both sides confirmed the end of the conflict and their will to jointly chart a peaceful and prosperous future.","topic":"Azerbaijan-Armenia conflict","kind":"fact"},{"t":232,"quote":"Moreover, by unilaterally lifting transit restrictions, Azarbaijan facilitates transportation of goods to and from Armenia.","topic":"Azerbaijan-Armenia conflict","kind":"fact"},{"t":239,"quote":"We have also established bilateral trade. Aarban provides strategically important oil products to Armenia on a regular basis.","topic":"Azerbaijan-Armenia conflict","kind":"fact"},{"t":316,"quote":"Today, more than 90,000 people live, study, and work in the liberated territories.","topic":"Azerbaijan reconstruction","kind":"number"},{"t":336,"quote":"Since the liberation of occupied territories in 2020, more than 400 individuals, including women and children, became victim to landmines.","topic":"Azerbaijan landmines","kind":"number"},{"t":345,"quote":"The cumulative toll of landmines over the past 30 years exceed 3,500 peoples.","topic":"Azerbaijan landmines","kind":"number"},{"t":367,"quote":"the need to clarify the fate and whereabouts of nearly 4,000 Azerbaijanis who went missing due to the conflict","topic":"Azerbaijan landmines","kind":"number"},{"t":426,"quote":"receiving international recognition, including through a series of United Nations General Assembly resolutions","topic":"Intercultural dialogue","kind":"fact"},{"t":504,"quote":"The conference delivered several historic agreements including the tripling of the global climate finance goal, full apersonalization of article 6 carbon market mechanism and further advancement of arrangements supporting the loss and damage fund for vulnerable communities affected by climate change.","topic":"Azerbaijan climate policy","kind":"fact"},{"t":536,"quote":"This September for the first time Baku hosted the UNF C climate week bringing together governments, international organizations, the private sector and other stakeholders to advance implementation and practical solutions.","topic":"Azerbaijan climate policy","kind":"fact"},{"t":568,"quote":"Since 2020, we have provided humanitarian, economic, and technical assistance, wars, approximately USD 400 million to more than 140 countries.","topic":"Azerbaijan aid","kind":"number"},{"t":578,"quote":"As we mark the 40th anniversary of the declaration on the right to development, Azarbaijan reaffirms its commitment to partnership based approaches founded on solidarity, mutual respect, and shared development priorities.","topic":"Azerbaijan aid","kind":"fact"},{"t":625,"quote":"In less than two decades, Azarbaian's GDP has increased three-fold while the poverty rate has declined from 49 to around 5%.","topic":"Azerbaijan economy","kind":"number"},{"t":635,"quote":"At the same time, Azarbaijan maintains one of the lowest levels of public external debt globally.","topic":"Azerbaijan economy","kind":"fact"},{"t":650,"quote":"At Azarbajan's initiative on 30 March 2026, the UN Human Rights Council adopted by consensus for the third time the resolution entitled promoting human rights and the sustainable development goals through transparent, accountable and efficient public service delivery.","topic":"Azerbaijan economy","kind":"fact"},{"t":667,"quote":"Co-sponsored by more than 100 member states, the resolution underscores the essential role of citizen- centered, transparent, and efficient public institutions in advancing human rights and accelerating progress toward the SDGs.","topic":"Azerbaijan economy","kind":"fact"},{"t":680,"quote":"Azarbaijan's innovative Assan and DOS models of transparent, accessible, and citizen- centered public service delivery have gained international recognition and are increasingly being adopted by dozens of partner countries.","topic":"Azerbaijan economy","kind":"self_credit"},{"t":709,"quote":"In this context, Azarbaijan's successful hosting of the 13th session of the World Urban Forum marked an important contribution to the global urban agenda.","topic":"Azerbaijan urbanization","kind":"fact"},{"t":718,"quote":"The key outcomes of the forum, the Baku call to action and the chair summary subsequently contributed to the high level meeting of the general assembly on midterm review of the new urban agenda held in New York in July this year.","topic":"Azerbaijan urbanization","kind":"fact"},{"t":780,"quote":"As a reliable natural gas supplier to 16 countries, Azarbaijan ranks among the leading pipeline gas suppliers globally","topic":"Azerbaijan energy","kind":"fact"},{"t":815,"quote":"Agreements already signed and vis around 6 gawatt of additional solar and wind capacity by 2030.","topic":"Azerbaijan energy","kind":"number"},{"t":822,"quote":"By 2030, renewables are expected to generate almost 40% of Azarbaan's","topic":"Azerbaijan energy","kind":"number"},{"t":864,"quote":"Since 2022, we have witnessed an increase in cargo volumes along the middle corridor by almost 90%.","topic":"Middle Corridor","kind":"number"},{"t":871,"quote":"Strategic infrastructure projects along the middle corridor speetheaded by Azarbaijan, including the Baku International Sea Trade Board and the Bakud Bilis cars railway are helping to create more resilient, diversified and sustainable supply chains between Asia and Europe.","topic":"Middle Corridor","kind":"fact"},{"t":914,"quote":"This project envisage an advanced fiber optic network across the Caspian Sea, further strengthening Azarbai's role as a regional digital hub and a key link between Europe and Asia.","topic":"Middle Corridor","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"UNGA","text":"And now I give the floor to his excellency Jaun Aiz Bramov, Minister for Foreign Affairs of Azer Mr. President, Mr. [clears throat] Secretary General, excellencies, ladies and gentlemen, at the outset, I warmly congratulate his excellency Mr. Khalil Rahman on assuming the presidency of the 81st session of the general assembly and wish him every success in this important position. I also thank his excellency Mr. Antonio Gutes, Secretary General of the United Nations for his endeavors. Ladies and gentlemen, as global challenges become increasingly complex, no country can address them alone."},{"t":68,"topic":"UN reform","text":"And yet the growing limitations of multilateral mechanisms continue to undermine our collective ability to respond effectively to current and emerging threats. Meeting these realities requires joint action. But true transformation is impossible without first restoring trust in the international order and demonstrating that multilateralism can once again deliver tangible results for all. In an era marked by division, growing intolerance and stark double standards, Azarbaijan advocates for a reinvigorated and reformed multilateral system underpinned by strict atterance to consistent and non- selective application of universally accepted norms and principles of international law. Aarban supports a more effective UN capable of delivering tangible results for member states especially in peace and security development, climate resilience and humanitarian action through inclusive multilateralisms."},{"t":135,"topic":"UN reform","text":"All states large or small participularly developing countries must have the opportunity to participate equally in global decision making. In this context, reform of the UN security is essential to make it more representative, effective, and responsive. Ladies and gentlemen, restoring global trust begins first and foremost with respecting international law, sovereign equality, and peaceful coexistence. It is exactly these principles that are guiding our efforts for peace and stability in the south caucuses. Even though the decadesl long conflict with Armenia brought immense tragedy to our people and left deep scars across our land, Azerbaijan has chosen to look ahead and turn the page of enmity. We offered Armenia peace fully in line with norms and principles of international law based on mutual recognition of and respect for each other's sovereignty and territorial integrity."},{"t":198,"topic":"Azerbaijan-Armenia conflict","text":"Our normalization efforts produced historic results at the Washington peace summit last August where the leaders of Aarban and Armenia signed a joint declaration witnessed by President Trump of the United States of America. Through this declaration, both sides confirmed the end of the conflict and their will to jointly chart a peaceful and prosperous future. The sides also initial the agreement on establishment of peace and interstate Today we have achieved the factor peace. Moreover, by unilaterally lifting transit restrictions, Azarbaijan facilitates transportation of goods to and from Armenia. We have also established bilateral trade. Aarban provides strategically important oil products to Armenia on a regular basis. Despite increased volatility in markets and growing international demand for these commodities, as we proceed with the peace agenda initiated by Azarbaan, our entire region is now turning into a promising anchor of stability, connectivity and tangible economic dividends."},{"t":266,"topic":"Azerbaijan reconstruction","text":"To make this process irreversible, it is of crucial importance to eliminate the remaining obstacle which will allow for finalization of the normalization process through the signing of the already initial bilateral agreement. complementing the regional normalization process, Azarbaijan's postconlict rehabilitation agenda aims to ensure that hundreds of thousands of Azerbaijanis can eventually exercise their right to a safe and dignified return to their homes. Due to large-scale reconstruction efforts taken by the government, life is now returning to our liberated territories. Azarbajan is rebuilding the entire region through smart cities and smart villages powered by green technology. Areas that were once rubble and ashes are now rising as modern settlements. Today, more than 90,000 people live, study, and work in the liberated territories. Regretfully, a massive contamination of the territories of Azerbaijan with landmines and other explosive devices remains a serious obstacle."},{"t":332,"topic":"Azerbaijan landmines","text":"This significantly abstracts the reconstruction and return process. Since the liberation of occupied territories in 2020, more than 400 individuals, including women and children, became victim to landmines. The cumulative toll of landmines over the past 30 years exceed 3,500 peoples. Given the scale of the problem, Azarbaijan considers mine action an essential prerequisite for fulfilling human rights and has formally decreed humanitarian demining its 18th national sustainable development goal. Similarly, the need to clarify the fate and whereabouts of nearly 4,000 Azerbaijanis who went missing due to the conflict is essential not only for accountability and the rights of the victims and their families but also for postconlict reconciliation and normalization. Mr. President, in the face of increasingly complex global challenges, our collective response must be inclusive, equitable, and universal."},{"t":394,"topic":"Intercultural dialogue","text":"Azarbajan's own experience reflects these principles. Our society is inherently multicultural and multiconfessional shaped by centuries of peaceful coexistence of diverse ethnic, cultural and religious communities. This tradition is reflected in Azarbaijan's international initiatives including the world forum on intercultural dialect. Launched in 2008 in the framework of the Bahu process, the forum has evolved into a prominent global platform for advancing intercultural dialect and cultural diversity, receiving international recognition, including through a series of United Nations General Assembly resolutions. Building upon these values, under the leadership of the president of the Republic of Azarbajan, his excellency Mr. Hamaliv Azerbajan has taken important steps to strengthen international solidarity to build bridges and to mobilize collective This commitment has also been demonstrated through successful hosting and steering of major global gatherings including COP 29 the 13 session of the world urban forum results oriented chairmanships of the non-aligned movement the organization of Turk states and the conference on interaction and confidence building measures in Asia and Azarbaijan's increasingly active engagement across other international Azarbaian's full-fledged membership in the consultive Meeting of heads of state of Central Asia and the C6 format will enhance our contribution to cooperation and"},{"t":485,"topic":"Azerbaijan climate policy","text":"connectivity within the region and COP 29 provided a good example of this approach in practice. As host and presidency, Azarbaijan guided negotiations toward ambitious and balanced outcomes while working to ensure that all voices were heard. The conference delivered several historic agreements including the tripling of the global climate finance goal, full apersonalization of article 6 carbon market mechanism and further advancement of arrangements supporting the loss and damage fund for vulnerable communities affected by climate change. Our efforts to advance climate action likewise did not end with COP 29. Azarbaijan continues to build on its legacy with particular focus on translating negotiated outcomes into practical implementation. This September for the first time Baku hosted the UNF C climate week bringing together governments, international organizations, the private sector and other stakeholders to advance implementation and practical solutions."},{"t":550,"topic":"Azerbaijan aid","text":"Azarban's commitment to international solidarity and cooperation is equally reflected in our development and humanitarian assistance. In recent years, Azarbaijan has significantly expanded the scope of its international aid with particular attention to small island developing states and African partner countries. Since 2020, we have provided humanitarian, economic, and technical assistance, wars, approximately USD 400 million to more than 140 countries. As we mark the 40th anniversary of the declaration on the right to development, Azarbaijan reaffirms its commitment to partnership based approaches founded on solidarity, mutual respect, and shared development priorities. Ladies and gentlemen, as we inch closer to 2030, it is becoming even more apparent that the world remains off track in implementing the sustainable development goals. Azarbaijan is firmly committed to the 23rd agenda for sustainable development having integrated the SDGs into its national development strategies, institutional frameworks and voluntary national review processes while placing particular emphasis on connectivity, green growth, digitalization and sustainable urban development."},{"t":625,"topic":"Azerbaijan economy","text":"In less than two decades, Azarbaian's GDP has increased three-fold while the poverty rate has declined from 49 to around 5%. At the same time, Azarbaijan maintains one of the lowest levels of public external debt globally. Our commitment also extends to advancing sustainable development through effective and accountable institutions. At Azarbajan's initiative on 30 March 2026, the UN Human Rights Council adopted by consensus for the third time the resolution entitled promoting human rights and the sustainable development goals through transparent, accountable and efficient public service delivery. Co-sponsored by more than 100 member states, the resolution underscores the essential role of citizen- centered, transparent, and efficient public institutions in advancing human rights and accelerating progress toward the SDGs. Azarbaijan's innovative Assan and DOS models of transparent, accessible, and citizen- centered public service delivery have gained international recognition and are increasingly being adopted by dozens of partner countries."},{"t":695,"topic":"Azerbaijan urbanization","text":"Sustainable urbanization is another important pillar of our approach to the 23rd agenda. Resilient cities are essential to improving quality of life, strengthening communities, and promoting inclusive economic and social development. In this context, Azarbaijan's successful hosting of the 13th session of the World Urban Forum marked an important contribution to the global urban agenda. The key outcomes of the forum, the Baku call to action and the chair summary subsequently contributed to the high level meeting of the general assembly on midterm review of the new urban agenda held in New York in July this year. At the same time, environmental protection remains an important national and regional priority. We are particularly concerned by continuing decline of the Caspian Sea with serious implications for biodiversity, livelihoods and economic activity across the region. As a challenge shared by all Caspian literal states, it requires a coordinated collective and sustained while remaining firmly commitment to our climate goals, we must also recognize that in the immediate term, development cannot realistically proceed without traditional energy sources."},{"t":772,"topic":"Azerbaijan energy","text":"Energy security, moreover, is closely intertwined with peace, regional connectivity, and sustainable economic development. As a reliable natural gas supplier to 16 countries, Azarbaijan ranks among the leading pipeline gas suppliers globally and plays a strategic role in strengthening energy security and diversifying supply routes across Europe and beyond. Azarban's contribution to global energy security is increasingly complemented by its growing role in the clean energy transition. We are investing in renewable energy, commissioning major solar and wind projects, expanding hydroar power capacity and developing new clean energy initiative together with leading international partners. Agreements already signed and vis around 6 gawatt of additional solar and wind capacity by 2030. By 2030, renewables are expected to generate almost 40% of Azarbaan's Expansion of renewable power generation will create new opportunities for Azarbaijan to export green electricity to European markets."},{"t":837,"topic":"Middle Corridor","text":"This way, our role as a reliable energy partner is evolving alongside the global energy transition. Energy connectivity is part of Azarbaijan's broader vision of connecting regions, markets, and economies. Azerbajan has emerged as a key transport and logistics hub between Europe and Asia, contributing to major trans regional connectivity initiatives, investing in modern transport infrastructure and expanding cooperation with regional partners. Since 2022, we have witnessed an increase in cargo volumes along the middle corridor by almost 90%. Strategic infrastructure projects along the middle corridor speetheaded by Azarbaijan, including the Baku International Sea Trade Board and the Bakud Bilis cars railway are helping to create more resilient, diversified and sustainable supply chains between Asia and Europe. These growths demonstrate the Middle Corridor's considerable potential as a key driver of regional connectivity, trade facilitation, and sustainable economic development."},{"t":899,"topic":"Middle Corridor","text":"Our connectivity agenda extends beyond energy and transport. Digital connectivity offers another important area for regional cooperation. Azarbajan is advancing new digital links across the region through ambitious initiatives such as a digital silkway. This project envisage an advanced fiber optic network across the Caspian Sea, further strengthening Azarbai's role as a regional digital hub and a key link between Europe and Asia. This broader connectivity agenda is also closely linked to the emerging peace architecture in the south caucuses. The Trump route for international peace and prosperity. Another key outcome of the 2025 Washington summit is expected to facilitate unimpeded multimodal connectivity between the main part of Aarban and its Nakuanom Republic and unlock new opportunities for regional trade, economic integration and prosperity as part of the Zanguzur Mr. President, ladies and gentlemen, in conclusion, I wish to reiterate that our shared challenges demand renewed global solidarity, more effective and trusted multilateralism grounded in international law and a reinvigorated system of cooperation."},{"t":973,"topic":"UN reform","text":"Trust, however, must be restored through concrete actions. Peace must be built on the ground. Commitments must be translated into real outcomes and sustainable development must deliver meaningful improvements in people's Azarbaian has consistently upheld the purposes and principles of the UN charter and demonstrated its firm adherence to international law including respect for sovereignty and territorial integrity non-inference in the internal affairs of states sovereign equality dialogue and cooperation as well as the faithful consistent and non- selective implementation of agreed commitments. This is the multilateralism we believe in. Principled, inclusive, and above all capable of delivering tangible results. I thank you. &gt;&gt; Thank you. I thank the Minister for Foreign Affairs of Azrajan."}],"compare":[{"topic":"UN & its reform","share":0.2509,"mean":0.2045,"rank":67,"others":170},{"topic":"Central Asia","share":0.1308,"mean":0.0019,"rank":1,"others":5},{"topic":"Cultural Restitution","share":0.0896,"mean":0.0002,"rank":1,"others":1},{"topic":"Armenia","share":0.0651,"mean":0.0015,"rank":3,"others":3}]};
